<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { api, idempotencyKey } from '../api/http'
const tab=ref('assessments'), assessments=ref<any[]>([]), wrong=ref<any[]>([]), mastery=ref<any[]>([]), directions=ref<any[]>([]), diag=reactive({directionId:undefined as number|undefined,durationMinutes:30,difficulty:3}), taking=ref(false), detail=ref<any>(), attempt=ref<any>(), answers=reactive<Record<number,any>>({}), result=ref<any>(), submitting=ref(false)
async function load(){const [a,w,m,d]=await Promise.all([api<any>({url:'/assessments',params:{pageSize:100}}),api<any[]>({url:'/wrong-questions'}),api<any[]>({url:'/mastery'}),api<any[]>({url:'/learning-directions'})]);assessments.value=a.items;wrong.value=w;mastery.value=m;directions.value=d;diag.directionId=Number(d[0]?.id)}
onMounted(load)
async function diagnostic(){const a=await api<any>({method:'POST',url:'/diagnostics',data:diag});await begin(a);await load()}
async function begin(a:any){detail.value=await api<any>({url:`/assessments/${a.publicId}`});attempt.value=await api<any>({method:'POST',url:`/assessments/${a.publicId}/attempts`});result.value=undefined;Object.keys(answers).forEach(k=>delete answers[Number(k)]);taking.value=true}
async function saveAnswer(sequence:number){await api({method:'PUT',url:`/attempts/${attempt.value.publicId}/answers/${sequence}`,data:{answer:answers[sequence]}})}
async function submit(){submitting.value=true;try{for(let i=0;i<detail.value.questions.length;i++)if(answers[i+1]!==undefined)await saveAnswer(i+1);await api({method:'POST',url:`/attempts/${attempt.value.publicId}/submission`,headers:{'Idempotency-Key':idempotencyKey()}});result.value=await api<any>({url:`/attempts/${attempt.value.publicId}/result`});ElMessage.success('已交卷，掌握度证据已更新');await load()}finally{submitting.value=false}}
function options(q:any){return q.options||[]}
</script>
<template><div><div class="page-head"><div><h2>评估是校准，不是评判</h2><p>诊断结果、练习表现、项目证据与间隔复习共同形成掌握度；自评置信度上限为 0.2。</p></div></div><div class="diagnostic panel"><div><span class="eyebrow">QUICK DIAGNOSTIC</span><h3>生成一次自适应诊断</h3><p>从公共题库抽取与你方向和难度匹配的题目。</p></div><el-select v-model="diag.directionId"><el-option v-for="d in directions" :key="d.id" :value="Number(d.id)" :label="d.name"/></el-select><el-select v-model="diag.difficulty"><el-option v-for="n in 5" :key="n" :value="n" :label="`难度 ${n}`"/></el-select><el-button type="primary" :disabled="!diag.directionId" @click="diagnostic">开始诊断</el-button></div><section class="panel assessment-panel"><el-tabs v-model="tab"><el-tab-pane label="评估记录" name="assessments"><el-table :data="assessments"><el-table-column prop="title" label="评估" min-width="260"/><el-table-column prop="type" label="类型" width="120"/><el-table-column prop="durationMinutes" label="时长" width="100"/><el-table-column prop="passScore" label="通过分" width="100"/><el-table-column prop="status" label="状态" width="110"/><el-table-column label="操作" width="100"><template #default="{row}"><el-button link type="primary" @click="begin(row)">开始</el-button></template></el-table-column></el-table></el-tab-pane><el-tab-pane :label="`错题本 ${wrong.length}`" name="wrong"><el-table :data="wrong"><el-table-column prop="questionId" label="题目编号"/><el-table-column prop="wrongCount" label="错误次数"/><el-table-column prop="lastWrongAt" label="最近错误"/><el-table-column prop="status" label="状态"/></el-table></el-tab-pane><el-tab-pane label="知识掌握度" name="mastery"><div v-if="!mastery.length" class="empty">完成诊断或学习任务后生成掌握度证据</div><div v-for="m in mastery" :key="m.knowledgePointId" class="mastery"><div><b>知识点 #{{m.knowledgePointId}}</b><small>{{m.level}} · {{m.evidenceCount}} 条证据</small></div><el-progress :percentage="Number(m.score)*100" :stroke-width="9"/><span>置信度 {{Math.round(Number(m.confidence)*100)}}%</span></div></el-tab-pane></el-tabs></section><el-dialog v-model="taking" :title="detail?.assessment?.title||'在线评估'" width="760" :close-on-click-modal="false"><template v-if="!result"><div v-for="(q,i) in detail?.questions" :key="i" class="question"><b>{{i+1}}. {{q.stem}}</b><el-radio-group v-if="options(q).length" v-model="answers[i+1]" class="options" @change="saveAnswer(i+1)"><el-radio v-for="(o,n) in options(q)" :key="n" :value="String.fromCharCode(65+n)">{{String.fromCharCode(65+n)}}. {{o}}</el-radio></el-radio-group><el-input v-else v-model="answers[i+1]" type="textarea" :rows="3" @blur="saveAnswer(i+1)"/></div><div class="submit-row"><span class="muted">答案实时保存；交卷操作具有幂等保护</span><el-button type="primary" :loading="submitting" @click="submit">确认交卷</el-button></div></template><template v-else><div class="result"><span>{{result.attempt.score??0}}</span><h3>本次评估已完成</h3><p>状态 {{result.attempt.gradingStatus}} · 及格线 {{detail.assessment.passScore}}</p><el-table :data="result.answers"><el-table-column prop="sequence" label="#" width="60"/><el-table-column prop="correct" label="正确" width="80"/><el-table-column prop="score" label="得分"/><el-table-column prop="analysis" label="解析"/></el-table></div></template></el-dialog></div></template>
<style scoped>.diagnostic{display:grid;grid-template-columns:1fr 190px 130px auto;gap:15px;align-items:center;background:#173d31;color:white;margin-bottom:18px}.diagnostic h3{margin:7px 0}.diagnostic p{color:#bcd0c6;font-size:12px;margin:0}.assessment-panel{min-height:440px}.mastery{display:grid;grid-template-columns:190px 1fr 100px;align-items:center;gap:20px;border-top:1px solid var(--line);padding:15px}.mastery b,.mastery small{display:block}.mastery small,.mastery>span{font-size:10px;color:var(--muted)}.question{padding:18px 4px;border-bottom:1px solid var(--line)}.options{display:flex;flex-direction:column;align-items:start;margin-top:14px;gap:7px}.submit-row{display:flex;justify-content:space-between;align-items:center;margin-top:20px}.result{text-align:center}.result>span{font:54px 'DM Serif Display';color:var(--green)}@media(max-width:800px){.diagnostic{grid-template-columns:1fr}.mastery{grid-template-columns:1fr}}</style>
